def transform(grid):
    h, w = len(grid), len(grid[0])

    # A uniform framed field reduces to the color at its marked corners.
    border = set(grid[0] + grid[-1] + [row[0] for row in grid] + [row[-1] for row in grid])
    if len(border) <= 2 and len(set(v for row in grid[1:-1] for v in row[1:-1])) == 1:
        corners = [grid[0][0], grid[0][-1], grid[-1][0], grid[-1][-1]]
        marked = [v for v in corners if v != grid[1][1]]
        return [[marked[0] if marked else corners[0]]]

    # The grid is a tiled field. Marker colors occur at intersections of
    # separator rows and columns; decode those intersection values.
    colors = {}
    for row in grid:
        for v in row:
            colors[v] = colors.get(v, 0) + 1
    base = max(colors, key=colors.get)

    marker_rows = [r for r in range(h)
                   if sum(1 for v in grid[r] if v not in (base,)) >= 2]
    marker_cols = [c for c in range(w)
                   if sum(1 for r in range(h) if grid[r][c] != base) >= 2]

    def periodic_coords(coords):
        if not coords:
            return []
        groups = []
        for x in coords:
            if not groups or x - groups[-1][-1] > 1:
                groups.append([x])
            else:
                groups[-1].append(x)
        return [round(sum(g) / len(g)) for g in groups]

    rs = periodic_coords(marker_rows)
    cs = periodic_coords(marker_cols)

    # Separator crossings encode the compact picture; discard the leading
    # boundary separator where present.
    if len(rs) > 1:
        rs = rs[1:]
    if len(cs) > 1:
        cs = cs[1:]
    return [[grid[r][c] for c in cs] for r in rs]
