def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the regular separator lattice from rows/columns containing
    # marker colors (colors other than the two repeating tile colors).
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    tile_colors = {v for v, _ in counts.most_common(2)}

    def lattice_coords(n, step, offset=0):
        return list(range(offset, n, step))

    # Separator crossings in these grids lie on a regular 4/5-cell lattice.
    best = None
    for sr in range(2, 7):
        for sc in range(2, 7):
            for ro in range(sr):
                for co in range(sc):
                    rs = lattice_coords(h, sr, ro)
                    cs = lattice_coords(w, sc, co)
                    score = sum(grid[r][c] not in tile_colors
                                for r in rs for c in cs)
                    if best is None or score > best[0]:
                        best = (score, rs, cs)

    _, rs, cs = best
    vals = [[grid[r][c] for c in cs] for r in rs]

    # Remove an all-background perimeter where present.
    while len(vals) > 1 and all(v in tile_colors for v in vals[0]):
        vals.pop(0)
    while len(vals) > 1 and all(v in tile_colors for v in vals[-1]):
        vals.pop()
    while vals and all(row[0] in tile_colors for row in vals):
        for row in vals:
            row.pop(0)
    while vals and all(row[-1] in tile_colors for row in vals):
        for row in vals:
            row.pop()
    return vals
